const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=null,page='life',filter='all',toastTimer;const KEY='lignees-save-v1';
try{const saved=JSON.parse(localStorage.getItem(KEY));if(valid(saved)){if(saved.version===1&&!localStorage.getItem(KEY+'-avant-v2'))localStorage.setItem(KEY+'-avant-v2',JSON.stringify(saved));state=Life.ensure(saved)}}catch(e){}
function valid(s){return s&&[1,2].includes(s.version)&&typeof s.seed==='string'&&Number.isFinite(s.rng)&&Number.isFinite(s.year)&&s.person&&Number.isFinite(s.person.age)&&Array.isArray(s.person.children)&&Array.isArray(s.ancestors)&&Array.isArray(s.journal)}
const money=n=>Math.round(n).toLocaleString('fr-FR')+' <small>UPA</small>';
const plain=n=>Math.round(n).toLocaleString('fr-FR');
const icon='<svg viewBox="0 0 30 38" fill="none"><path d="M15 35V5M15 19L4 9M15 26L26 15M4 9V3M26 15V7M15 5l6-4M15 5L9 1" stroke-width="1.7"/><circle cx="15" cy="35" r="2" fill="#c5df9c" stroke="none"/></svg>';
const tabs=[['life','◷','Ma vie'],['actions','✧','Possibilités'],['career','↗','Carrière'],['projects','◈','Projets'],['money','↗','Patrimoine'],['people','♧','Relations'],['family','⑂','Ma lignée'],['journal','≡','Journal']];
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4000)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch(e){toast('La sauvegarde locale est indisponible. Exportez votre partie.');return false}}
function nav(id){page=id;render();window.scrollTo({top:0,behavior:'smooth'})}
function render(){if(!state)return welcome();const p=state.person,c=Life.country(state);$('#app').innerHTML=`<aside class="sidebar"><div class="brand">${icon}lignées<span style="font-size:9px;letter-spacing:0;color:var(--muted);align-self:end;padding-bottom:5px">2.0</span></div><div class="eyebrow nav-label">Une vie à écrire</div><nav class="nav">${(typeof visibleTabs==='function'?visibleTabs():tabs).map(([id,i,t])=>`<button class="${page===id?'active':''}" onclick="nav('${id}')"><span class="ico">${i}</span>${t}</button>`).join('')}</nav><div class="side-bottom"><div class="eyebrow">Votre univers</div><div>Génération ${state.generation} · ${state.year}</div><div style="margin-top:18px"><button onclick="settings()">⚙ &nbsp; Partie & sauvegarde</button></div><button onclick="sources()">ⓘ &nbsp; Le modèle & les données</button><div style="margin-top:23px;font-size:10px;line-height:1.8">Une vie parmi des milliards.<br>Une histoire qui vous appartient.</div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Votre histoire <span>/ &nbsp; ${esc(tabs.find(t=>t[0]===page)?.[2])}</span></div><div class="top-actions"><span class="saved"><i class="dot"></i>Sauvegarde locale</span><button class="pill" onclick="settings()">Seed : ${esc(state.seed.slice(0,15))} ↗</button></div></header><div class="content">${typeof timelineHUD==='function'?timelineHUD():''}${({life:lifeView,actions:actionsView,career:careerView,projects:projectsView,money:moneyView,people:peopleView,family:familyView,journal:journalView}[page]||lifeView)()}</div></main><nav class="tabs-mobile">${(typeof visibleTabs==='function'?visibleTabs():tabs).map(([id,i,t])=>`<button class="${page===id?'active':''}" onclick="nav('${id}')"><span>${i}</span>${t}</button>`).join('')}</nav>`}
function heading(title,sub,extra=''){return`<div class="intro-row"><div><h1>${title}</h1><p>${sub}</p></div>${extra}</div>`}
function profile(){const p=state.person,c=Life.country(state);return`<section class="profile"><div class="avatar">${esc(p.name[0]+p.surname[0])}</div><div><h2>${esc(p.name)} ${esc(p.surname)}</h2><div class="meta"><span>⌖ ${esc(c.name)}</span><span>◌ ${esc(p.job)}</span><span>⑂ Génération ${state.generation}</span></div></div><div class="ageblock"><b>${p.age}</b> <span>ans</span><small>${state.year} · ${p.alive?'Une histoire en cours':'Une vie accomplie'}</small></div></section>`}
function stat(label,value,bar){return`<div class="stat"><div class="stat-top">${label}<span>${label==='Patrimoine net'?'↗':'◌'}</span></div><b>${value}</b>${bar!==undefined?`<div class="bar"><i style="width:${Math.round(bar)}%;background:${bar<30?'var(--red)':'var(--green)'}"></i></div>`:'<div style="height:16px"></div>'}</div>`}
function lifeView(){const s=state,p=s.person,c=Life.country(s);return`${heading('Chaque choix écrit la suite.','Le hasard vous a donné un départ. À vous d’inventer le chemin.',`<span class="pill"><i class="dot"></i>${p.alive?'Votre vie est en cours':'Votre héritage continue'}</span>`)}${profile()}<div class="stats">${stat('Santé',`${Math.round(p.health)} <em>/ 100</em>`,p.health)}${stat('Épanouissement',`${Math.round(p.happiness)} <em>/ 100</em>`,p.happiness)}${stat('Énergie',`${Math.round(p.energy)} <em>/ 100</em>`,p.energy)}${stat('Patrimoine net',money(Life.balance(p)))}</div><div class="layout"><div><div class="section-head"><h3>${p.alive?'Le prochain chapitre':'Une vie, des traces'}</h3><span class="eyebrow">${s.year} · ${p.age} ans</span></div>${!p.alive?ending():s.pending?eventView():`<div class="card event"><div class="eyebrow">À votre rythme</div><h2>La suite vous attend.</h2><p>Vous pouvez explorer les possibilités de cette année, ou laisser le temps avancer.</p><button class="btn primary" onclick="advance()">Continuer ma vie →</button></div>`}<div class="section-head" style="margin-top:29px"><h3>Les derniers instants</h3><button class="muted" style="font-size:11px" onclick="nav('journal')">Tout le journal ↗</button></div>${timeline(s.journal.filter(x=>x.person===p.id).slice(-5).reverse())}</div><aside class="right"><div class="card"><h3>Votre équilibre</h3><div class="data-row"><span>Temps disponible</span><b>${'●'.repeat(p.points)}${'○'.repeat(3-p.points)} &nbsp; ${p.points}/3</b></div><div class="data-row"><span>Stress</span><b style="color:${p.stress>70?'var(--red)':'inherit'}">${Math.round(p.stress)} / 100</b></div><label>Votre priorité cette année</label><select onchange="act('focus',this.value)">${[['balance','Un peu de tout'],['career','Carrière & ambition'],['family','Relations & famille'],['health','Santé & sérénité']].map(([v,t])=>`<option value="${v}" ${p.focus===v?'selected':''}>${t}</option>`).join('')}</select><button class="btn" style="width:100%;margin-top:15px" onclick="nav('actions')">✧ Explorer mes possibilités</button></div><div class="card"><h3>Le monde autour de vous</h3><div class="data-row"><span>Lieu de vie</span><b>${esc(c.name)}</b></div><div class="data-row"><span>Conjoncture</span><b>${s.recession?'Ralentissement':'Économie en mouvement'}</b></div><div class="data-row"><span>Marché cette année</span><b style="color:${s.market<0?'var(--red)':'var(--green)'}">${s.market>=0?'+':''}${(s.market*100).toFixed(1)} %</b></div><p class="hint">Les événements personnels et économiques sont des estimations de gameplay. Le futur est un scénario, pas une prévision.</p></div><div class="card"><h3>Le temps vous appartient</h3><p class="hint">Les actions libres utilisent votre temps disponible. Les grands choix restent accessibles. Avancer renouvelle votre temps.</p><button class="btn primary next" ${!p.alive||s.pending?'disabled':''} onclick="advance()">Vivre une année de plus &nbsp; →</button>${s.pending?'<div class="hint">Choisissez d’abord votre prochain chapitre.</div>':''}</div></aside></div>`}
function eventView(){const e=state.pending;return`<article class="card event"><div class="eyebrow">✧ &nbsp; Une décision à prendre</div><h2>${esc(e.title)}</h2><p>${esc(e.text)}</p><div class="choices">${e.choices.map((x,i)=>`<button class="choice" onclick="decide(${i})"><span><strong>${esc(x.label)}</strong><small>${esc(x.note)}</small></span><span class="arrow">↗</span></button>`).join('')}</div></article>`}
function timeline(entries){return`<div class="timeline">${entries.map(x=>`<div class="entry ${x.important?'important':''}"><time>${x.year} &nbsp; · &nbsp; ${x.age} ans</time><p>${esc(x.text)}</p></div>`).join('')||'<div class="empty">Les premières pages restent à écrire.</div>'}</div>`}
function ending(){const p=state.person;return`<div class="result"><div class="eyebrow">${state.year-p.age} — ${state.year}</div><h2 style="margin-top:15px">${esc(p.name)}, ${p.age} ans de possibles.</h2><p>Une vie ${p.moves?'traversée par le mouvement':'ancrée dans son époque'}, ${p.children.length?`prolongée par ${p.children.length} enfant${p.children.length>1?'s':''}`:'faite de liens, de choix et d’expériences'}. Vous laissez un patrimoine net de ${plain(Life.balance(p))} UPA et une histoire qui ne se résume pas à ce chiffre.</p><div class="row" style="margin-top:15px"><button class="btn primary" onclick="nav('family')">Découvrir mon héritage →</button><button class="btn" onclick="newGame()">Une autre vie</button></div></div>`}
const actionCards=[['learn','Apprendre & me former','Développez vos compétences. +5 compétence, −5 énergie.','Apprendre'],['job','Trouver un emploi','La qualification et les compétences modifient les chances de trouver un poste.','Chercher un poste'],['rest','Ralentir un instant','Retrouver de l’énergie, réduire le stress et prendre soin de soi.','Prendre du repos'],['sport','Bouger, respirer','Santé +4, stress −4. Installe aussi une habitude sportive durable.','Faire du sport'],['social','Nourrir mes liens','Du temps pour vos amis, votre couple et vos enfants.','Voir mes proches'],['date','Faire une rencontre','65 % de chance simulée qu’une relation commence. Disponible hors couple.','Rencontrer'],['child','Un projet d’enfant','En couple, de 21 à 45 ans. Chance simulée de 15 à 65 % selon l’âge.','Essayer'],['adopt','Accueillir un enfant','De 25 à 60 ans. Coût : 20 % du revenu de référence local. Démarche simplifiée.','Adopter'],['business','Lancer mon activité','Capital : 20 % du revenu de référence. Clients incertains, bénéfices variables.','Entreprendre'],['home','Un toit à moi','Apport : un revenu de référence annuel. Crédit et entretien à prévoir.','Acheter un logement'],['migrate','Vivre ailleurs','Démarches incertaines. Budget, qualification et compétences comptent.','Explorer les pays'],['breakup','Prendre un autre chemin','Terminer votre relation. Coût simulé : 15 % des liquidités.','Me séparer']];
function actionsView(){const p=state.person;return`${heading('La vie ne tient pas dans un seul choix.','Prenez des initiatives entre les grands tournants.',`<span class="pill">${p.points} action${p.points>1?'s':''} disponible${p.points>1?'s':''}</span>`)}<div class="filter">${[['all','Tout explorer'],['work','Travail & projets'],['self','Pour moi'],['links','Mes liens']].map(([id,t])=>`<button onclick="filter='${id}';render()" class="${filter===id?'active':''}">${t}</button>`).join('')}</div>${!p.alive?'<div class="notice">Cette vie est terminée. Vous pouvez poursuivre votre lignée.</div>':''}<div class="grid">${actionCards.filter(([id])=>filter==='all'||(filter==='work'?['job','learn','business','home','migrate']:filter==='self'?['rest','sport','learn']:['date','child','adopt','social','breakup']).includes(id)).map(([id,t,d,b])=>`<div class="card"><div class="eyebrow" style="margin-bottom:13px">${['rest','sport','learn','social'].includes(id)?'Accessible dès l’enfance':'Vie adulte'} · 1 temps</div><h3>${t}</h3><p>${d}</p><button class="btn" ${!p.alive||p.points===0?'disabled':''} onclick="${id==='migrate'?'migration()':`act('${id}')`}">${b} ↗</button></div>`).join('')}</div>`}
function moneyView(){const p=state.person,net=Life.income(state)-Life.costs(state),hist=state.history.slice(-25);return`${heading('Ce que vous construisez.','Les montants sont exprimés en unités de pouvoir d’achat (UPA), une monnaie de jeu comparable.')}<div class="stats">${stat('Patrimoine net',money(Life.balance(p)))}${stat('Liquidités',money(p.cash))}${stat('Revenus annuels',money(Life.income(state)))}${stat('Dépenses courantes',money(Life.costs(state)))}</div><div class="grid"><div class="card"><h3>Votre trajectoire</h3><div class="big-number">${money(Life.balance(p))}</div><div class="chart">${hist.map(x=>`<div title="${x.year} : ${plain(x.value)} UPA" style="height:${Math.max(3,Math.abs(x.value)/Math.max(1,...hist.map(h=>Math.abs(h.value)))*85)}px;background:${x.value<0?'var(--red)':'#8aa66d'}"></div>`).join('')||'<p>Votre histoire financière commence ici.</p>'}</div><small>Les ${hist.length} dernières années · valeur nette</small></div><div class="card"><h3>Budget & habitudes</h3><div class="data-row"><span>Solde avant dette et entretien</span><b>${money(net)}</b></div><label>Niveau de vie</label><select onchange="act('lifestyle',this.value)">${[['frugal','Sobre · dépenses réduites'],['normal','Équilibré'],['comfort','Confortable · dépenses élevées']].map(([v,t])=>`<option value="${v}" ${p.lifestyle===v?'selected':''}>${t}</option>`).join('')}</select><label>Part du surplus investie automatiquement : <b id="saving-value">${p.saving} %</b></label><input aria-label="Épargne automatique" type="range" min="0" max="80" value="${p.saving}" oninput="document.getElementById('saving-value').textContent=this.value+' %'" onchange="act('saving',this.value)"><p class="hint">Le reste du surplus rejoint vos liquidités. Un déficit crée une dette. Taux simplifié : 4,5 % par an.</p></div>${[['funds','Portefeuille diversifié','Exposé au marché mondial simulé. Les baisses peuvent durer ; aucun rendement garanti.'],['speculation','Placements spéculatifs','Variations annuelles très fortes. Vous pouvez perdre une grande partie du capital.']].map(([id,t,d])=>`<div class="card"><div class="eyebrow">Investissement</div><h3 style="margin-top:12px">${t}</h3><div class="big-number">${money(p[id])}</div><p>${d}</p><div class="row"><button class="btn" ${!p.alive?'disabled':''} onclick="investment('${id}','invest')">Investir ↗</button><button class="btn" ${!p.alive?'disabled':''} onclick="investment('${id}','withdraw')">Vendre</button></div></div>`).join('')}<div class="card"><h3>Immobilier</h3><div class="big-number">${money(p.home)}</div><p>${p.home?'Entretien annuel : 1,2 % de la valeur. Votre logement réduit certaines dépenses courantes.':'Un logement s’achète avec un apport et un crédit. Le prix peut monter ou baisser.'}</p><button class="btn" onclick="act('${p.home?'sellhome':'home'}')" ${!p.alive?'disabled':''}>${p.home?'Vendre mon logement':'Devenir propriétaire'}</button></div><div class="card"><h3>Entreprise & dette</h3><div class="data-row"><span>Valeur de votre activité</span><b>${money(p.business?.value||0)}</b></div><div class="data-row"><span>Bénéfice annuel</span><b>${money(p.business?.profit||0)}</b></div><div class="data-row"><span>Dette totale</span><b>${money(p.debt)}</b></div><div class="row"><button class="btn" onclick="act('${p.business?'sellbusiness':'business'}')" ${!p.alive?'disabled':''}>${p.business?'Céder mon activité':'Créer une activité'}</button><button class="btn" onclick="act('repay')" ${!p.alive?'disabled':''}>Rembourser la dette</button></div></div></div><div class="notice">Modèle économique de jeu : fiscalité, salaires et placements sont simplifiés. Les UPA ne sont pas une devise réelle. Aucun de ces chiffres ne constitue une prévision financière.</div>`}
function peopleView(){const p=state.person;return`${heading('Les vies qui croisent la vôtre.','Le temps partagé entretient les liens. Les absences et les décisions laissent aussi des traces.')}<div class="grid"><div class="card"><h3>Votre couple</h3>${p.partner?personRow(p.partner.name,`${p.partner.age} ans · confiance ${Math.round(p.partner.bond)}/100`):'<p>Votre histoire amoureuse reste ouverte.</p>'}<button class="btn" onclick="act('${p.partner?'social':'date'}')" ${!p.alive?'disabled':''}>${p.partner?'Passer du temps ensemble':'Faire une rencontre'} ↗</button></div><div class="card"><h3>Vos enfants</h3>${p.children.map(x=>personRow(x.name,`${x.age} ans · lien ${Math.round(x.bond)}/100 · envie de ${x.ambition}`)).join('')||'<p>Vous n’avez pas d’enfant. Il existe de nombreuses façons de construire une vie.</p>'}<div class="row"><button class="btn" onclick="act('child')" ${!p.alive?'disabled':''}>Projet d’enfant</button><button class="btn" onclick="act('adopt')" ${!p.alive?'disabled':''}>Adoption</button></div></div><div class="card"><h3>Vos racines</h3>${p.parents.map(x=>personRow(x.name,`Lien familial : ${Math.round(x.bond)}/100`)).join('')}<p class="hint">Les parents de départ sont des figures narratives ; leur santé et leur succession ne sont pas encore simulées individuellement.</p></div><div class="card"><h3>Votre cercle</h3>${p.friends.slice(-8).map(x=>personRow(x.name,`Lien : ${Math.round(x.bond)}/100`)).join('')||'<p>Des rencontres vous attendent.</p>'}<button class="btn" onclick="act('social')" ${!p.alive?'disabled':''}>Entretenir mes liens</button></div></div>`}
function personRow(name,sub,button=''){return`<div class="person"><div class="avatar">${esc(name[0])}</div><div><b>${esc(name)}</b><small>${esc(sub)}</small></div>${button}</div>`}
function familyView(){const p=state.person;return`${heading('Une histoire plus grande que vous.','L’argent se transmet. Les liens, les possibilités et les souvenirs aussi.',`<span class="pill">Génération ${state.generation}</span>`)}${!p.alive?ending():''}<div class="card"><div class="eyebrow">L’arbre de votre lignée</div>${state.ancestors.map(x=>personRow(x.name+' '+x.surname,`${x.age} ans · ${x.alive?'retrait du contrôle':'vie terminée'} · patrimoine ${plain(Life.balance(x))} UPA`)).join('')}${personRow(p.name+' '+p.surname,`${p.age} ans · vous incarnez cette vie`)}${p.children.map(x=>personRow(x.name+' '+x.surname,`${x.age} ans · ${x.ambition}`,`<button class="btn" onclick="handoff(${x.id})">Incarner ↗</button>`)).join('')}${!p.children.length?'<p style="margin-top:20px">Aucun descendant pour le moment. Votre histoire peut continuer autrement : nouvelle naissance ou autre branche sauvegardée.</p>':''}</div><div class="grid"><div class="card"><h3>Passer le relais</h3><p>Vous pouvez incarner un enfant à son âge actuel. Son éducation, ses compétences, ses liens et son épargne ont déjà évolué. Votre chronologie continue sans revenir en arrière.</p><p>De votre vivant, aucun patrimoine n’est transféré automatiquement. Au décès, le patrimoine net positif est partagé : moitié au partenaire s’il existe, puis entre les enfants.</p></div><div class="card"><h3>Explorer une autre branche</h3><p>Exportez votre sauvegarde avant une grande décision pour conserver cette branche. Vous pourrez l’importer plus tard, ou recommencer avec la même seed et le même contexte.</p><button class="btn" onclick="exportSave()">Exporter cette branche ↗</button><button class="btn" onclick="replay()">Rejouer le même départ</button></div></div><div class="notice">La continuité conserve les événements passés. Cette version ne permet pas encore de revenir à l’enfance d’un descendant dans une chronologie alternative.</div>`}
function journalView(){return`${heading('Les pages de votre vie.','Des tournants, des tentatives et tout ce qui reste entre les deux.',`<button class="btn" onclick="exportJournal()">Exporter le récit ↗</button>`)}<div class="filter"><button class="${filter!=='highlights'?'active':''}" onclick="filter='all';render()">Tous les instants</button><button class="${filter==='highlights'?'active':''}" onclick="filter='highlights';render()">Grands tournants</button></div><div class="card">${timeline(state.journal.filter(x=>filter!=='highlights'||x.important).slice().reverse())}</div>`}
function welcomeBase(){const params=new URLSearchParams(location.search);$('#app').innerHTML=`<div class="welcome"><header><div class="brand">${icon}lignées</div><button class="pill" onclick="sources()">Le hasard, expliqué ↗</button></header><section class="hero"><div class="eyebrow">Une simulation de vie & de générations</div><h1>Une vie.<br><span>Mille possibles.</span></h1><p>Vous ne choisissez pas votre naissance.<br>Mais chaque décision peut changer ce qui vient après.<br>Et l’histoire ne s’arrête pas toujours à vous.</p></section><section class="birth-box"><h3>Où votre histoire commencera-t-elle ?</h3><label for="country">Votre naissance</label><select id="country"><option value="random">Au hasard dans le monde</option>${Life.countries.filter(c=>c.code!=='XX').map(c=>`<option value="${c.code}">${c.name} — scénario choisi</option>`).join('')}</select><div class="grid"><div><label for="seed">Seed de votre univers</label><input id="seed" maxlength="40" placeholder="Laissez le hasard décider" value="${esc(params.get('seed')||'')}"></div><div><label for="birthyear">Année de naissance</label><select id="birthyear"><option value="2026">2026 · Monde contemporain</option><option value="1990">1990 · Scénario rétrospectif</option><option value="2050">2050 · Futur imaginé</option></select></div></div><button class="btn primary" onclick="start()">Commencer une vie &nbsp; →</button><p class="hint">Une vie complète, à votre rythme. Aucun compte nécessaire. Sauvegarde automatique sur cet appareil.</p></section><footer>Naissance pondérée par des parts approximatives des naissances mondiales.<br>Les autres probabilités sont des modèles de jeu, identifiés comme tels.<br><button style="color:var(--green);margin-top:15px" onclick="importSave()">↥ Importer une partie</button></footer></div>`}
function start(){const code=$('#country').value,year=Number($('#birthyear').value),seed=$('#seed').value.trim()||crypto.getRandomValues(new Uint32Array(1))[0].toString(36).toUpperCase();state=Life.create(seed,code,year);state.initial={code,year};save();page='life';render();window.scrollTo(0,0)}
function decide(i){if(Life.choose(state,i)){save();render()}}
function advance(){if(Life.year(state)){save();render();window.scrollTo({top:0,behavior:'smooth'})}else toast('Répondez d’abord à la décision en cours.')}
function act(type,value){const r=Life.action(state,type,value);if(r.ok){save();render()}toast(r.message||'Action indisponible.')}
function modal(html){const d=$('#modal');d.innerHTML=`<button class="close" aria-label="Fermer" onclick="document.getElementById('modal').close()">×</button>${html}`;if(!d.open)d.showModal()}
function investment(asset,type){const p=state.person,max=type==='invest'?p.cash:p[asset];modal(`<h2>${type==='invest'?'Investir':'Vendre une position'}</h2><p>${asset==='funds'?'Portefeuille diversifié':'Placement spéculatif'} · disponible : ${plain(max)} UPA</p><label for="amount">Montant en UPA</label><input id="amount" type="number" min="1" max="${Math.floor(max)}" value="${Math.floor(max*.25)}"><button class="btn primary" style="margin-top:20px" onclick="executeInvestment('${asset}','${type}')">Confirmer</button><p class="hint">Aucun temps consommé. Le résultat futur reste incertain.</p>`)}
function executeInvestment(asset,type){const n=Number($('#amount').value);const r=Life.action(state,type,{asset,amount:n});if(r.ok){$('#modal').close();save();render()}toast(r.message)}
function migration(){modal(`<h2>Un nouveau pays, une autre vie.</h2><p>Une migration demande du temps, un budget et des démarches. Le poste actuel sera quitté si le projet aboutit. Le partenaire et les enfants suivent dans ce modèle simplifié.</p><label for="destination">Destination</label><select id="destination">${Life.countries.filter(c=>c.code!==state.person.country&&c.code!=='XX').map(c=>`<option value="${c.code}">${c.name}</option>`).join('')}</select><p>Probabilité simulée : ${Math.round(Life.clamp(.2+state.person.education*.12+state.person.skill*.004,.15,.85)*100)} %. Les frais sont engagés même en cas d’échec.</p><button class="btn primary" onclick="const dest=document.getElementById('destination').value;document.getElementById('modal').close();act('migrate',dest)">Tenter le départ →</button>`)}
function handoff(id){const x=state.person.children.find(x=>x.id===id);modal(`<h2>Incarner ${esc(x.name)} ?</h2><p>Vous continuerez en ${state.year}, à ${x.age} ans. ${state.person.alive?'Votre personnage actuel deviendra un ancêtre suivi en arrière-plan.':'La succession sera répartie entre le partenaire éventuel et les enfants.'} Cette action change le personnage contrôlé.</p><div class="row"><button class="btn" onclick="exportSave()">Exporter avant le relais</button><button class="btn primary" onclick="confirmHandoff(${id})">Poursuivre avec ${esc(x.name)} →</button></div>`)}
function confirmHandoff(id){if(Life.inherit(state,id)){save();$('#modal').close();page='life';render();toast('Un nouveau chapitre dans la même histoire.')}}
function settings(){modal(`<h2>Votre partie</h2><p>${state?'Seed : '+esc(state.seed)+' · génération '+state.generation:'Votre prochaine vie vous attend.'}</p><div class="choices">${state?'<button class="choice" onclick="exportSave()"><strong>Exporter la sauvegarde</strong><span>↗</span></button><button class="choice" onclick="replay()"><strong>Rejouer le même départ</strong><span>↗</span></button>':''}<button class="choice" onclick="importSave()"><strong>Importer une sauvegarde</strong><span>↥</span></button>${state?'<button class="choice" onclick="shareSeed()"><strong>Partager la seed de départ</strong><span>↗</span></button>':''}<button class="choice" onclick="newGame()"><strong>Commencer une autre vie</strong><span>→</span></button></div><p class="hint">La sauvegarde automatique reste dans ce navigateur. Exportez-la pour la transférer ou garder plusieurs branches.</p>`)}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportSave(){if(state)download('lignees-'+state.seed+'-g'+state.generation+'.json',JSON.stringify(state,null,2));toast('Sauvegarde exportée.')}
function exportJournal(){download('lignees-recit.txt',state.journal.map(x=>`${x.year} · ${x.age} ans — ${x.text}`).join('\n\n'),'text/plain')}
function importSave(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const f=input.files[0];if(!f||f.size>5e6)throw Error();const s=JSON.parse(await f.text());if(!valid(s))throw Error();state=Life.ensure(s);save();if($('#modal').open)$('#modal').close();page='life';render();toast('Votre histoire reprend.')}catch(e){toast('Sauvegarde invalide ou incompatible. Votre partie actuelle est conservée.')}};input.click()}
function newGame(){if(!state){$('#modal').close();welcome();return}modal('<h2>Une nouvelle naissance ?</h2><p>Votre sauvegarde automatique sera remplacée au démarrage de la nouvelle vie. Exportez-la pour garder cette branche.</p><div class="row"><button class="btn" onclick="exportSave()">Exporter ma partie</button><button class="btn primary" onclick="state=null;document.getElementById(\'modal\').close();welcome()">Choisir un nouveau départ →</button></div>')}
function replay(){modal('<h2>Revivre le même départ ?</h2><p>Le pays, le foyer et les premiers tirages seront identiques avec la même version du moteur. Vos choix pourront modifier la suite.</p><div class="row"><button class="btn" onclick="exportSave()">Exporter cette branche</button><button class="btn primary" onclick="confirmReplay()">Recommencer →</button></div>')}
function confirmReplay(){const i=state.initial||{code:'random',year:state.startYear};state=Life.create(state.seed,i.code,i.year);state.initial=i;save();$('#modal').close();page='life';render()}
async function shareSeed(){const url=new URL(location.href);url.search='';url.searchParams.set('seed',state.seed);try{await navigator.clipboard.writeText(url.href);toast('Lien copié. Sélectionnez les mêmes réglages pour reproduire le départ.')}catch(e){modal(`<h2>Votre seed</h2><p>${esc(state.seed)}</p><p>Copiez cette seed et utilisez les mêmes réglages de naissance.</p>`)}}
function sourcesBase(){modal(`<h2>Le hasard, expliqué.</h2><p><b>Lignées est une simulation jouable en bêta.</b> Elle combine un départ pondéré à l’échelle mondiale et des règles de gameplay. Elle ne prédit pas le destin d’une personne.</p><h3>Naissances & pays</h3><p>24 profils nationaux et un groupe « autres pays ». Les poids représentent des volumes annuels de naissances approximatifs, normalisés par le moteur. Les revenus de référence et espérances de vie sont des ordres de grandeur illustratifs, non une base officielle synchronisée.</p><h3>Décisions & risques</h3><p>Emploi, relations, parentalité, marchés, migrations et entreprises utilisent des hypothèses explicites de jeu. La mortalité est un modèle d’âge ajusté au profil du pays et à la santé ; elle n’est pas calibrée sur des tables nationales par âge. Les chiffres historiques et futurs restent des scénarios utilisant ces mêmes profils.</p><h3>Limites de cette version</h3><p>Fiscalité et droits de succession simplifiés ; coûts en UPA ; pas de simulation juridique ou médicale. Les identités et familles sont fictives. Les prénoms proviennent d’un répertoire commun et ne reflètent pas une distribution culturelle.</p><div class="sources"><a href="https://population.un.org/wpp/" target="_blank" rel="noopener">ONU · World Population Prospects ↗</a><a href="https://pip.worldbank.org/" target="_blank" rel="noopener">Banque mondiale · Poverty and Inequality Platform ↗</a></div><p class="hint">Ces références orientent la conception ; les données complètes ne sont pas encore intégrées à cette version. Le moteur et les sauvegardes sont versionnés pour assurer une reproductibilité.</p>`)}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
